const extraComponents={
 avocado:{id:'avocado',name:'Palta cruda (pulpa)',unit:'g',k:1.60,p:.02,c:.0853,f:.1466,fi:.067},
 bacon:{id:'bacon',name:'Panceta cocida (modelo genérico)',unit:'g',k:5.4,p:.37,c:.014,f:.42,fi:0}
};
const aliases={'McDonald’s':['mcdonalds','mc donalds','mcdonald','macdonalds','mcdonald s'],'Burger King':['burger','burguer king','bk'],'Starbucks':['starbucks','sturbucks'],'Café Martínez':['cafe martinez','martinez'],'Tienda de Café':['tienda de cafe'],'SushiClub':['sushi club','sushiclub'],'Fabric Sushi':['fabric','fabrik'],'Ishidan Sushi':['ishidan']};
export const RESTAURANT_ALIASES=Object.fromEntries([...RESTAURANT_OFFICIAL,...RESTAURANT_MODELS].map(r=>[r.id||'rest_'+r.key,[r.brand,...(aliases[r.brand]||[]),'restaurante','cadena','menu']]));
const icons={burger:'🍔',fries:'🍟',coffee:'☕',pastry:'🥐',sandwich:'🥪',dessert:'🍰',chicken:'🍗',sushi:'🍣',dish:'🍽️'};
export const RESTAURANT_VISUALS=Object.fromEntries([...RESTAURANT_OFFICIAL,...RESTAURANT_MODELS].map(r=>[r.id||'rest_'+r.key,{icon:icons[r.kind]||icons.dish,label:r.brand+' · '+r.name}]));
export function buildRestaurantCatalog(baseFoods){
 const map=new Map([...baseFoods,...Object.values(extraComponents)].map(f=>[f.id,f]));
 const foods=RESTAURANT_OFFICIAL.map(r=>({id:r.id,name:r.brand+' · '+r.name+' ('+r.grams+' g)',brand:r.brand,category:'restaurant',unit:'g',restaurant:true,diaryOnly:true,servingGrams:r.grams,
 ...Object.fromEntries(['k','p','c','f','fi'].map(key=>[key,r[key]/r.grams])),
 sourceType:'manufacturer_web_label',validationStatus:'rotulo_web_fabricante',sourceUrl:r.sourceUrl,
 source:'Ficha web oficial de McDonald’s Argentina consultada el 14/11/2026. Por producto de '+r.grams+' g: '+r.k+' kcal; P '+r.p+' g; HC '+r.c+' g; G '+r.f+' g; fibra '+r.fi+' g. '+r.reviewNote+' No incluye papas ni bebida, salvo que el nombre las indique.'}));
 for(const r of RESTAURANT_MODELS){
  const totals={k:0,p:0,c:0,f:0,fi:0},parts=[];
  for(const [id,qty] of Object.entries(r.parts)){
   const f=map.get(id);if(!f)throw Error('Missing restaurant reference '+id);
   for(const key of Object.keys(totals))totals[key]+=f[key]*qty;
   parts.push(qty+' '+f.unit+' de '+f.name+' ['+id+']');
  }
  foods.push({id:'rest_'+r.key,name:r.brand+' · '+r.name+' (estimación)',brand:r.brand,category:'restaurant',unit:r.unit,restaurant:true,diaryOnly:true,comboPieces:r.comboPieces||null,servingGrams:r.portion,recipeParts:r.parts,
  ...Object.fromEntries(Object.entries(totals).map(([k,v])=>[k,v/r.portion])),sourceType:'recipe_estimate',validationStatus:'receta_estimado',sourceUrl:r.menuUrl,
  source:'ESTIMACIÓN NUTRICIONAL, no tabla de la cadena. Nombre identificado en carta o canal comercial; disponibilidad variable por sucursal. Peso/volumen y cantidades SUPUESTOS: '+parts.join('; ')+'. Rendimiento de referencia: '+r.portion+' '+r.unit+'. Modelo con equivalentes genéricos del catálogo; NO representa la receta exacta del restaurante. '+r.note+' Micronutrientes no estimados. Revisado 14/11/2026.'});
 }
 const portions=Object.fromEntries(foods.map(f=>[f.id,{grams:f.servingGrams,label:(f.comboPieces?'combo de '+f.comboPieces+' piezas':RESTAURANT_VISUALS[f.id].icon==='🍣'?'pieza':f.unit==='ml'?'vaso':'porción')+' de '+f.servingGrams+' '+f.unit}]));
 return {foods,portions};
}
